definition.raw:
In this case,  the tracking error for each agent is defined as
\begin{equation}
  \label{II03}
  e_i = h_i(x_i)+q(w_i).

[\textbf{State Feedback Synchronized Regulator Problem}] Find, if possible, $\alpha_i(x_i,w_i)$ for node $i$ such that:
  \begin{enumerate}
    \item [1a)] the equilibrium $x=0$ of
    \begin{equation}  \label{II08}
      \dot{x}_i = f_i(x_i)+g_i(x_i)\alpha_i(x_i,0), \quad i\in\mathcal{V}
    \end{equation}
    is exponentially stable.
    \item [1b)] there are a neighborhood $U\subset X\times W$ of $(0,0)$ and a exosystem,
    \begin{equation} \label{II09}
      \dot{w}_0=s(w_0),
    \end{equation}
    defined on the neighborhood $W_0$ of origin of $\mathbb{R}^{s}$, such that, for each initial condition $(x(0),w(0))\in U$, there exists a initial condition $w_0(0)\in W_0$ for system \eqref{II09} such that the solution of \eqref{II05} satisfies
    \begin{equation}
      \label{II10}
      \lim_{t\rightarrow \infty} (h_i(x_i(t))+q(w_0(t))) = 0, \quad \forall\, i\in\mathcal{V}.
    \end{equation}
  \end{enumerate}

[\textbf{Error feedback Synchronized Regulator Problem}] Find, if possible, $\alpha_i(z_i,w_i)$ and $\eta_i(z_i,y_i)$, such that
  \begin{itemize}
    \item [2a)] the equilibrium $(x,z)=0$ of
    \begin{equation} \label{II11}
    \begin{split}
      &\dot{x}_i=f_i(x_i)+g_i(x_i)\alpha_i(z_i,0),\\
      & \dot{z}_i=\eta_i(z_i,h_i(x_i)),
      \end{split}\quad \quad i\in\mathcal{V},
    \end{equation}
  is exponentially stable.
  \item [2b)] there exists a neighborhood $U\subset X\times Z\times W$ of $(0,0,0)$ and an exosystem
  \begin{equation} \label{II12}
    \dot{w}_0=s(w_0)
  \end{equation}
  defined on a neighborhood $W_0$ of origin of $\mathbb{R}^{s}$, such that, for each initial condition $(x(0), z(0)$, $ w(0))\in U$, there exists a initial condition $w_0(0)\in W_0$ for system \eqref{II12} such that the solution of \eqref{II07} satisfies
  \begin{equation}
    \label{II13}
    \lim_{t\rightarrow \infty} (h_i(x_i(t))+q(w_0(t)))=0, \quad \forall\, i\in\mathcal{V}.
  \end{equation}
  \end{itemize}

_0=s(w_0)$ is defined as \cite{CenciniBOOK2010}
\begin{equation}
  \nu_{max} = \lim_{t\rightarrow \infty} \lim_{\delta w^0\rightarrow 0}\frac{1}{t} \ln\frac{\|\Phi_t^s(w^0+\delta w^0)-\Phi_t^s(w^0)\|}{\|\delta w^0\|}
\end{equation}

On the other hand, consider the consensus rate of a switching graph.

satisfying Assumption A4) with given $t$ and $T$, its
consensus convergent rate is defined as the supremum of the contract rate of transition matrix $\Phi(t+(k-1)T,t+kT)$ \cite{XiangIJC2011},
\begin{equation}
  \alpha^*(T,t)=\sup_k \alpha(\Phi(t+(k-1)T,t+kT))
\end{equation}
where the contract rate $\alpha(\Phi)$ is defined as $\alpha(\Phi) = \max\limits_{x\neq 0, x\bot \mathbf{b}}\frac{\|\Phi^Tx\|}{\|x\|}$, and the transition matrix is defined as
\begin{equation} \label{III03}
  \Phi(t^2,t^1)=e^{-L^{\sigma_j}(t^2-t_{j-1})}e^{-L^{\sigma_{j-1}}\delta_{j-1}}\cdots e^{-L^{\sigma_{i+1}}\delta_{i+1}}e^{-L^{\sigma_{i}}(t_i-t^1)}
\end{equation}
where $L^{\sigma_k}$ is the Laplacian matrix of graph $\mathcal{G}_{\sigma_k}$.

theorem.raw:
\label{th01}
Under assumption A1), A2) and A4), the state feedback synchronized regulator problem is solvable for the multi-agent system \eqref{II01} if and only if for all $i\in\mathcal{V}$, there exist $C^k(k\ge 2)$ mapping $x_i=\pi_i(w_0)$, with $\pi_i(0)=0$, and $u_i=c_i(w_0)$, with $c_i(0)=0$, both defined in a neighborhood $W^0$ of origin, satisfying the conditions
\begin{subequations} \label{III09}
\begin{align}
 \label{III09a} &\frac{\partial \pi_i}{\partial w_0} s(w_0) = f_i(\pi_i(w_0))+g_i(\pi_i(w_0))c_i(w_0) \\
 \label{III09b} &h_i(\pi_i(w_0))+q(w_0)=0
\end{align}
\end{subequations}

\label{th02}
Under assumptions A1)$\sim$A4), the output feedback synchronized regulator problem is solvable for the multi-agent system \eqref{II01} if and only if there exist $C^k(k\ge 2)$ mapping $x_i=\pi_i(w_0)$, with $\pi_i(0)=0$, and $u_i=c_i(w_0)$, with $c_i(0)=0$, both defined in a neighborhood $W^0$ of origin, satisfying the conditions
\setcounter{equation}{8}
\begin{subequations} \label{III09}
\begin{align}
 \label{III09a} &\frac{\partial \pi_i}{\partial w_0} s(w_0) = f_i(\pi_i(w_0))+g_i(\pi_i(w_0))c_i(w_0) \\
 \label{III09b} &h_i(\pi_i(w_0))+q(w_0)=0
\end{align}
\end{subequations}

Given a multi-agent system \eqref{II01} and an exosystem \eqref{IV01} satisfying assumptions A1)$\sim$A3) and $A5)$. There is a dynamic controller of the form
\begin{equation}
  \left\{ \begin{split}
  \dot{w}_i& =s(w_i)+\sum_{j=0}^N \bar{a}_{ij}^{\sigma(t)}(w_j-w_i))\\
  \dot{z}_i& = \eta_i(z_i,y_i)\\
    u_i &= \alpha_i(z_i,w_i)
\end{split},
\right. \quad i\in\mathcal{V}
\end{equation}
such that for all sufficiently small $x_i(0)$, $w_i(0)$, $z_i(0)$ and $w_0(0)$, the trajectory of the closed-loop system is bounded and satisfies
\begin{equation}
  \lim_{t\rightarrow 0} \left(h_i(x_i)+q(w_0)\right)\rightarrow 0,
\end{equation}
if and only if there exist $C^k(k\ge 2)$ mapping $x_i=\pi_i(w_0)$, with $\pi_i(0)=0$, and $u_i=c_i(w_0)$, with $c_i(0)=0$, both defined in a neighborhood $W^0$ of origin, satisfying the conditions
\begin{equation}
\begin{split}
 &\frac{\partial \pi_i}{\partial w_0} s(w_0) = f_i(\pi_i(w_0))+g_i(\pi_i(w_0))c_i(w_0) \\
&h_i(\pi_i(w_0))+q(w_0)=0
\end{split}, \quad i\in\mathcal{V}.
\end{equation}

lemma.raw:
\label{le01}
Given a multi-agent system \eqref{II02} with communication graph $\mathcal{G}_{\sigma(t)}$satisfying assumption A4). If the largest Lyapunov exponent $\nu_{max}$ of system $\dot{w}_0=s(w_0)$ and the consensus convergence rate $\alpha^*(T,t)$ of $\mathcal{G}_{\sigma(t)}$ are such that
\begin{equation}
  \label{III01}
  \nu_{max}+\ln(\alpha^*(T,t))/T<0
\end{equation}
then system \eqref{II02} is locally exponentially synchronizable.

\label{le03}
Given a multi-agent system \eqref{II01} with assumptions A1), A2) and A4). Suppose that for all $i\in\mathcal{V}$, there exist $C^k(k\ge 2)$ mapping $x_i=\pi_i(w_0)$, with $\pi_i(0)=0$, and $u_i=c_i(w_0)$, with $c_i(0)=0$, both defined in a neighborhood $W^0$ of origin, satisfying the conditions
\begin{subequations} \label{III09}
\begin{align}
 \label{III09a} &\frac{\partial \pi_i}{\partial w_0} s(w_0) = f_i(\pi_i(w_0))+g_i(\pi_i(w_0))c_i(w_0) \\
 \label{III09b} &h_i(\pi_i(w_0))+q(w_0)=0
\end{align}
\end{subequations}
then under the following controller
\begin{equation}
  \label{III10}
  u_i = \alpha_i(x_i,w_i)=c_i(w_i)+K_i(x_i-\pi_i(w_i)), \quad i\in\mathcal{V}.
\end{equation}
where $K_i$ is such that $A_i+B_iK_i$ is Hurwitz, conditions 1a) and 1b) will be satisfied.

proof.raw:
According to Assumption A2), it is true that there exists a matrix $K_i$ such that $A_i+B_iK_i$ is Hurwitz for all $i\in\mathcal{V}$. Noting that $\alpha_i(x_i,0)=K_ix_i$, condition 1a) follows directly. Below we show condition 1b).

By Lemma \ref{le02}, there is a positive scalar $\beta_1$ such that
\begin{equation} \label{III11}
  \|\delta w_i(t)\| \le \epsilon_0 e^{-\beta_1t}\|\delta w_i(0)\|, \quad \forall\,\, i\in\mathcal{V},
\end{equation}
for some positive scalar $\epsilon_0$. Consider the vector $e_{xi}=x_i-\pi_i(w_0)$. With \eqref{III09a}, its dynamics has the form
\begin{equation} \label{III12}
  \dot{e}_{xi}=f_i(x_i)+g_i(x_i)\alpha_i(x_i,w_i)-f_i(\pi_i(w_0))-g_i(\pi_i(w_0))c_i(w_0).
\end{equation}
Making use of linear approximation and mean value theorem, one has,
\begin{equation}
  f_i(x_i)-f_i(\pi_i(w_0))=A_ie_{xi}+\psi_{f_i}(x_i)-\psi_{f_i}(\pi_i(w_0)) = A_ie_{xi}+\mathrm{M}\psi_{f_i}(\pi_i(w_0),e_{x_i})e_{x_i}
\end{equation}
and
\begin{equation}
\begin{split}
 g_i(x_i)&\alpha_i(x_i,w_i)-g_i(\pi_i(w_0))c_i(w_0)
 = g_i(x_i)c_i(w_i)-g_i(\pi_i(w_0))c_i(w_0)+g_i(x_i)K_ie_{xi}\\
 =&(g_i(x_i)-g_i(\pi_i(w_0)))c_i(w_0)+g_i(x_i)(\mathrm{M}c_i(w_0,\delta{w_i})\delta{w_i}+K_ie_{xi})\\
 =&B_iK_ie_{xi}+
  \left[\mathrm{M}g_{ij}(0,x_i)x_i,\cdots, \mathrm{M}g_{im_i}(0,x_i)x_i\right]K_ie_{xi}+ g_i(x_i)\mathrm{M}c_i(w_0,\delta{w_i})\delta{w_i}
 \\& +\left(\sum_{j=1}^{m_i} c_{ij}(w_0)\mathrm{M}g_{ij}(\pi_i(w_0),e_{xi})\right)e_{xi}
 \end{split}
\end{equation}
where $g_{ij}(x_i)$ denotes the $j$th column vector of matrix function $g_i(x_i)$ and $c_{ij}(w_0)$ denotes the $j$th element of $c_i(w_0)$. With the above two equations, equation \eqref{III12} can be rewritten as
\begin{equation}
  \dot{e}_{xi}=(A_i+B_iK_i)e_{xi}+ N(w_0,x_i)e_{xi}+g_i(x_i)\mathrm{M}c_i(w_0,\delta w_i)\delta w_i, \quad i\in\mathcal{V},
\end{equation}
where
\begin{equation}
\begin{split}
N(w_0,x_i)&=\mathrm{M}\psi_{f_i}(\pi_i(w_0),x_i-\pi_i(w_0))+\sum_{j=1}^{m_i} c_{ij}(w_0)\mathrm{M}g_{ij}(\pi_i(w_0),x_i-\pi_i(w_0)) \\&+
  \left[\mathrm{M}g_{ij}(0,x_i)x_i,\cdots, \mathrm{M}g_{im_i}(0,x_i)x_i\right]K_i
\end{split}.
\end{equation}
Since $A_i+B_iK_i$ is Hurwitz, there are a symmetric positive definite matrix $P_i\in\mathbb{R}^{n_i\times n_i}$ and a positive scalara $\epsilon_1$ such that
\begin{equation}
  \label{III17}
P_i(A_i+B_iK_i)+(A_i+B_iK_i)^TP_i+2\epsilon_1P_i<-I_{n_i}.
\end{equation}
By assumption A1) and noticing that condition 1a) holds, there exist sufficiently small $w_i(0)$ and $x_i(0)$ (notice that $w_0$ depends on $w_i$, $i\in\mathcal{V}$), such that the trajectories of $x_i(t)$ and $w_i(t)$ of the closed-loop system \eqref{II05} satisfy
\begin{equation}
  \|N(w_0(t),x_i(t))\|\le \frac{1}{2\lambda_M(P_i)},\,\, \,\, \|g_i(x_i(t))\mathrm{M}c_i(w_0(t),\delta w_i(t))\|\le \frac{1}{\lambda_M(P_i)}, \quad \forall t>0.
\end{equation}
where $\lambda_M(P_i)$ denotes the maximum eigenvalue of $P_i$.

Then consider the Lyapunov function $V_i=e_{xi}^TP_ie_{xi}$, whose derivative satisfies
\begin{equation}
  \dot{V}_i\le - 2\epsilon_1e_{xi}^TP_ie_{xi} + 2e_{xi}^TP_i g_i(x_i)\mathrm{M}c_i(w_0,\delta w_i)\delta w_i
  \le -2\epsilon_1 V_i + 2\epsilon_2 \sqrt{V_i}\|\delta w_i\|,
\end{equation}
where $\epsilon_2>\frac{1}{\sqrt{\lambda_{m}(P_i)}}$ is a constant scalar and $\lambda_m(P_i)$ denoting the minimal eigenvalue of $P_i$.

Define $\bar{V}_i=\sqrt{V}_i$, then $\bar{V}_i\ge0$ and
\begin{equation}
  \dot{\bar{V}}_i\le -\epsilon_1\bar{V}_i+\epsilon_2 \|\delta w_i\|,
\end{equation}
which is equivalent to $\left(e^{\epsilon_1t}\bar{V}_i\right)'\le \epsilon_2 e^{\epsilon_1t}\|\delta w_i\|$. With \eqref{III11}, one further obtains
\begin{equation}
  \bar{V}_i(t)\le  e^{-\epsilon_1 t}\left(\bar{V}_i(0)-\frac{\epsilon_2\epsilon_0\|\delta w_i(0)\|}{\epsilon_1-\beta_1} \right) + e^{-\beta_1 t}\frac{\epsilon_2\epsilon_0\|\delta w_i(0)\|}{\epsilon_1-\beta_1},
\end{equation}
from which, $\bar{V}_i(t)\rightarrow 0$ as $t\rightarrow \infty$, and so does $e_{xi}$. Using \eqref{III09b}, it can be further concluded that condition 1b) will be satisfied.

Necessity is clear. Below we show the sufficiency by using a constructive method. Assumption A2) and A3) mean that there are matrices $K_i$ and $L_i$ such that
\setcounter{equation}{21}
\begin{equation}
  A_i+B_iK_i \quad \mbox{and}\quad A_i+L_iC_i
\end{equation}
are Hurwitz. By them, the following matrix
\begin{equation} \label{III23}
  \begin{bmatrix}
    A_i & B_iK_i \\
    -L_iC_i & A_i+B_iK_i+L_iC_i
  \end{bmatrix}
\end{equation}
is also Hurwitz. Suppose there are two maps $\pi_i(w_0)$ and $c_i(w_0)$ satisfying \eqref{III09}, then set the dynamic controller to be
\begin{subequations} \label{III24}
\begin{align}
&u_i=\alpha_i(z_i,w_i)=c_i(w_i)+K_i(z_i-\pi_i(w_i)), \label{III24a}\\
&\dot{z}_{i}=\eta_i(z_i,h_i)=f_i(z_{i})+g_i(z_{i})u_i+L_i(h_i(z_i)-h_i(x_i)), \label{III24b}
\end{align}
\end{subequations}
for all $i\in\mathcal{V}$. Define the augmented state $\tilde{x}_i = [x_i^T, z_i^T]^T$, and maps
\begin{gather}
  \label{III25}
  \tilde{f}_i({\tilde{x}_i})=\begin{bmatrix}
    f_i(x_i)\\
    -L_ih_i(x_i)+L_ih_i(z_i)+f_i(z_i)
  \end{bmatrix}, \quad \tilde{g}_i(\tilde{x}_i)=\begin{bmatrix}
    g_i(x_i) \\ g_i(z_i)
  \end{bmatrix}, \nonumber \\
  \tilde{\pi}_i(w_0)=\begin{bmatrix}
    \pi_i(w_0) \\ \pi_i(w_0)
  \end{bmatrix}, \quad \tilde{h}_i(\tilde{x}_i)=h_i(x_i).
\end{gather}
With them, one has
\begin{equation} \label{III26}
  \dot{\tilde{x}}_i = \tilde{f}_i(\tilde{x}_i)+\tilde{g}_i(\tilde{x}_i)u_i, \quad \tilde{y}_i=\tilde{h}_i(\tilde{x}_i), \quad i\in\mathcal{V},
\end{equation}
and
\begin{equation} \label{III27}
\begin{split}
 &\frac{\partial \tilde{\pi}_i}{\partial w_0} s(w_0) = \tilde{f}_i(\tilde{\pi}_i(w_0))+\tilde{g}_i(\tilde{\pi}_i(w_0))c_i(w_0), \\
&\tilde{h}_i(\tilde{\pi}_i(w_0))+q(w_0)=0.
\end{split}
\end{equation}
The Jacobian matrices of $\tilde{f}_i(\tilde{x}_i)$ and $\tilde{g}_i(\tilde{x}_i)$ have the form of
\begin{equation}
  \tilde{A}_i=\left[
  \frac{\partial \tilde{f}_i}{\partial \tilde{x}_i}
  \right]_{\tilde{x}_i=0}=\begin{bmatrix}
    A_i & 0 \\
    -L_iC_i & A_i+L_iC_i
  \end{bmatrix}, \quad \tilde{B}_i=\left[
  \frac{\partial \tilde{g}_i}{\partial \tilde{x}_i}
  \right]_{\tilde{x}_i=0}=\begin{bmatrix}
    B_i & 0 \\
    0 & B_i
  \end{bmatrix}
\end{equation}
Noting that $\tilde{A}_i+\tilde{B}_i[0, K_i]$ has exactly the form \eqref{III23} and that controller \eqref{III24a} can be rewritten as $u_i=c_i(w_i)+[0, K_i](\tilde{x}_i-\tilde{\pi}_i(w_i))$, by Lemma \ref{le03} conditions 1a) and 1b) are satisfied for multi-agent system \eqref{III26} with controller \eqref{III24a}, and subsequently conditions 2a) and 2b) are satisfied for the closed-loop system \eqref{II07}. Therefore the output feedback synchronized regulator problem is solved under controller \eqref{III24}.

