\begin{equation}
  \alpha^*(T,t)=\sup_k \alpha(\Phi(t+(k-1)T,t+kT))
\end{equation}
where the contract rate $\alpha(\Phi)$ is defined as $\alpha(\Phi) = \max\limits_{x\neq 0, x\bot \mathbf{b}}\frac{\|\Phi^Tx\|}{\|x\|}$, and the transition matrix is defined as
\begin{equation} \label{III03}
  \Phi(t^2,t^1)=e^{-L^{\sigma_j}(t^2-t_{j-1})}e^{-L^{\sigma_{j-1}}\delta_{j-1}}\cdots e^{-L^{\sigma_{i+1}}\delta_{i+1}}e^{-L^{\sigma_{i}}(t_i-t^1)}
\end{equation}
where $L^{\sigma_k}$ is the Laplacian matrix of graph $\mathcal{G}_{\sigma_k}$. Throughout of this paper, $\mathbf{b}$ denotes the vector with all elements being $1$.

\begin{lemma} \label{le02}
