\end{proof}

\begin{proof}
According to Assumption A2), it is true that there exists a matrix $K_i$ such that $A_i+B_iK_i$ is Hurwitz for all $i\in\mathcal{V}$. Noting that $\alpha_i(x_i,0)=K_ix_i$, condition 1a) follows directly. Below we show condition 1b).

By Lemma \ref{le02}, there is a positive scalar $\beta_1$ such that
\begin{equation} \label{III11}
  \|\delta w_i(t)\| \le \epsilon_0 e^{-\beta_1t}\|\delta w_i(0)\|, \quad \forall\,\, i\in\mathcal{V},
\end{equation}
for some positive scalar $\epsilon_0$. Consider the vector $e_{xi}=x_i-\pi_i(w_0)$. With \eqref{III09a}, its dynamics has the form
\begin{equation} \label{III12}
  \dot{e}_{xi}=f_i(x_i)+g_i(x_i)\alpha_i(x_i,w_i)-f_i(\pi_i(w_0))-g_i(\pi_i(w_0))c_i(w_0).
\end{equation}
Making use of linear approximation and mean value theorem, one has,
\begin{equation}
  f_i(x_i)-f_i(\pi_i(w_0))=A_ie_{xi}+\psi_{f_i}(x_i)-\psi_{f_i}(\pi_i(w_0)) = A_ie_{xi}+\mathrm{M}\psi_{f_i}(\pi_i(w_0),e_{x_i})e_{x_i}
\end{equation}
and
\begin{equation}
\begin{split}
 g_i(x_i)&\alpha_i(x_i,w_i)-g_i(\pi_i(w_0))c_i(w_0)
 = g_i(x_i)c_i(w_i)-g_i(\pi_i(w_0))c_i(w_0)+g_i(x_i)K_ie_{xi}\\
 =&(g_i(x_i)-g_i(\pi_i(w_0)))c_i(w_0)+g_i(x_i)(\mathrm{M}c_i(w_0,\delta{w_i})\delta{w_i}+K_ie_{xi})\\
 =&B_iK_ie_{xi}+
  \left[\mathrm{M}g_{ij}(0,x_i)x_i,\cdots, \mathrm{M}g_{im_i}(0,x_i)x_i\right]K_ie_{xi}+ g_i(x_i)\mathrm{M}c_i(w_0,\delta{w_i})\delta{w_i}
 \\& +\left(\sum_{j=1}^{m_i} c_{ij}(w_0)\mathrm{M}g_{ij}(\pi_i(w_0),e_{xi})\right)e_{xi}
 \end{split}
\end{equation}
where $g_{ij}(x_i)$ denotes the $j$th column vector of matrix function $g_i(x_i)$ and $c_{ij}(w_0)$ denotes the $j$th element of $c_i(w_0)$. With the above two equations, equation \eqref{III12} can be rewritten as
\begin{equation}
  \dot{e}_{xi}=(A_i+B_iK_i)e_{xi}+ N(w_0,x_i)e_{xi}+g_i(x_i)\mathrm{M}c_i(w_0,\delta w_i)\delta w_i, \quad i\in\mathcal{V},
\end{equation}
where
\begin{equation}
\begin{split}
N(w_0,x_i)&=\mathrm{M}\psi_{f_i}(\pi_i(w_0),x_i-\pi_i(w_0))+\sum_{j=1}^{m_i} c_{ij}(w_0)\mathrm{M}g_{ij}(\pi_i(w_0),x_i-\pi_i(w_0)) \\&+
  \left[\mathrm{M}g_{ij}(0,x_i)x_i,\cdots, \mathrm{M}g_{im_i}(0,x_i)x_i\right]K_i
\end{split}.
\end{equation}
Since $A_i+B_iK_i$ is Hurwitz, there are a symmetric positive definite matrix $P_i\in\mathbb{R}^{n_i\times n_i}$ and a positive scalara $\epsilon_1$ such that
\begin{equation}
  \label{III17}
P_i(A_i+B_iK_i)+(A_i+B_iK_i)^TP_i+2\epsilon_1P_i<-I_{n_i}.
\end{equation}
By assumption A1) and noticing that condition 1a) holds, there exist sufficiently small $w_i(0)$ and $x_i(0)$ (notice that $w_0$ depends on $w_i$, $i\in\mathcal{V}$), such that the trajectories of $x_i(t)$ and $w_i(t)$ of the closed-loop system \eqref{II05} satisfy
\begin{equation}
  \|N(w_0(t),x_i(t))\|\le \frac{1}{2\lambda_M(P_i)},\,\, \,\, \|g_i(x_i(t))\mathrm{M}c_i(w_0(t),\delta w_i(t))\|\le \frac{1}{\lambda_M(P_i)}, \quad \forall t>0.
\end{equation}
where $\lambda_M(P_i)$ denotes the maximum eigenvalue of $P_i$.

Then consider the Lyapunov function $V_i=e_{xi}^TP_ie_{xi}$, whose derivative satisfies
\begin{equation}
  \dot{V}_i\le - 2\epsilon_1e_{xi}^TP_ie_{xi} + 2e_{xi}^TP_i g_i(x_i)\mathrm{M}c_i(w_0,\delta w_i)\delta w_i
  \le -2\epsilon_1 V_i + 2\epsilon_2 \sqrt{V_i}\|\delta w_i\|,
\end{equation}
where $\epsilon_2>\frac{1}{\sqrt{\lambda_{m}(P_i)}}$ is a constant scalar and $\lambda_m(P_i)$ denoting the minimal eigenvalue of $P_i$.

Define $\bar{V}_i=\sqrt{V}_i$, then $\bar{V}_i\ge0$ and
\begin{equation}
  \dot{\bar{V}}_i\le -\epsilon_1\bar{V}_i+\epsilon_2 \|\delta w_i\|,
\end{equation}
which is equivalent to $\left(e^{\epsilon_1t}\bar{V}_i\right)'\le \epsilon_2 e^{\epsilon_1t}\|\delta w_i\|$. With \eqref{III11}, one further obtains
\begin{equation}
  \bar{V}_i(t)\le  e^{-\epsilon_1 t}\left(\bar{V}_i(0)-\frac{\epsilon_2\epsilon_0\|\delta w_i(0)\|}{\epsilon_1-\beta_1} \right) + e^{-\beta_1 t}\frac{\epsilon_2\epsilon_0\|\delta w_i(0)\|}{\epsilon_1-\beta_1},
\end{equation}
